import json
from itertools import permutations

def compute_day_ranges(sequence, durations):
    starts = {}
    ends = {}
    current_start = 1
    for city in sequence:
        d = durations[city]
        start = current_start
        end = start + d - 1
        starts[city] = start
        ends[city] = end
        current_start = end  # overlap on flight day
    return starts, ends

def has_direct_flights(sequence, direct_edges):
    for i in range(len(sequence) - 1):
        if frozenset((sequence[i], sequence[i+1])) not in direct_edges:
            return False
    return True

def main():
    # Input variables (constraints)
    total_days = 16
    city_durations = {
        "Istanbul": 2,
        "Rome": 3,
        "Seville": 4,
        "Naples": 7,
        "Santorini": 4
    }
    # Anchored day windows (must exactly match due to specified durations)
    anchored_windows = {
        "Istanbul": (6, 7),
        "Santorini": (13, 16)
    }
    # Direct flights (undirected)
    direct_flights = {
        frozenset(("Rome", "Santorini")),
        frozenset(("Seville", "Rome")),
        frozenset(("Istanbul", "Naples")),
        frozenset(("Naples", "Santorini")),
        frozenset(("Rome", "Naples")),
        frozenset(("Rome", "Istanbul"))
    }

    cities = list(city_durations.keys())

    # Quick feasibility check on total days using overlap rule
    required_city_days = sum(city_durations.values())
    min_days_with_overlaps = required_city_days - (len(cities) - 1)
    if min_days_with_overlaps != total_days:
        # If this ever fails, no solution exists under given overlap rule
        print(json.dumps({"itinerary": []}))
        return

    solution = None

    for seq in permutations(cities):
        # Must visit all 5 cities once; permutations already ensures that
        # Check direct flights between consecutive cities
        if not has_direct_flights(seq, direct_flights):
            continue

        # Compute day ranges with overlap on flight days
        starts, ends = compute_day_ranges(seq, city_durations)

        # Total distinct days equals end of last city (since start at day 1)
        if ends[seq[-1]] != total_days:
            continue

        # Check anchored windows: must match exactly due to specified durations
        ok = True
        for city, (a_start, a_end) in anchored_windows.items():
            if not (starts.get(city) == a_start and ends.get(city) == a_end):
                ok = False
                break
        if not ok:
            continue

        # All constraints satisfied
        solution = [{"day_range": f"Day {starts[city]}-{ends[city]}", "place": city} for city in seq]
        break

    if solution is None:
        # No feasible itinerary found
        print(json.dumps({"itinerary": []}))
    else:
        print(json.dumps({"itinerary": solution}, ensure_ascii=False))

if __name__ == "__main__":
    main()
